#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""1M-row x 1K-indicator sweep experiment, generated by sweep_benchmark_gen.

Reads generated JSON on stdin. All reported wall times include SQL parsing and
execution. One untimed setup; strategy order rotates by repeat. No correctness
claim is made for Hyperscan outside this deliberately ASCII benchmark corpus.
"""
import argparse
import json
import time
import sys
from chdb import session

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--repeats', type=int, default=3)
parser.add_argument('--strategy', choices=['original_hyperscan','exhaustive_exact','constant_candidates','dynamic_needles'])
parser.add_argument('--ingest', action='store_true', help='Measure actual dynamic-watchlist MV insert throughput')
args = parser.parse_args()
spec = json.load(sys.stdin)
s = session.Session()

def rows(sql):
    return json.loads(s.query(sql, 'JSONCompact').data())['data']

s.query('SET max_threads=4, max_block_size=8192, max_insert_block_size=8192, min_insert_block_size_rows=8192, min_insert_block_size_bytes=0, max_memory_usage=4000000000')
print(json.dumps({'engine': rows('SELECT version()'), 'settings': rows("SELECT name,value FROM system.settings WHERE name IN ('max_threads','max_block_size','max_insert_block_size','min_insert_block_size_rows','min_insert_block_size_bytes','max_memory_usage','short_circuit_function_evaluation','max_query_size','max_ast_elements','max_expanded_ast_elements')")}), flush=True)
# Probe behavior rather than assuming lazy AND/if evaluation.
for setting in ['disable', 'enable', 'force_enable']:
    for name, expression in [('and', 'number != 0 AND throwIf(number = 0)'), ('if', 'if(number != 0, throwIf(number = 0), 0)')]:
        sql = f"SELECT {expression} FROM numbers(1) SETTINGS short_circuit_function_evaluation='{setting}'"
        try:
            result = rows(sql)
        except Exception as e:
            result = str(e)[:300]
        print(json.dumps({'short_circuit_probe': name, 'setting': setting, 'result': result}), flush=True)
s.query('CREATE TABLE bench (id UInt64, v String) ENGINE=MergeTree ORDER BY id')
s.query(f"INSERT INTO bench SELECT number, if(number % 100 = 0, concat('https://evil', leftPad(toString(intDiv(number,100) % 1000),4,'0'), '.example/path'), concat('https://benign.example/path/',toString(number))) FROM numbers({spec['rows']})")
print(json.dumps({'rows':spec['rows'], 'indicators':spec['indicators'], 'expected_hits': spec['rows']//100}), flush=True)
if args.ingest:
    strategy = args.strategy or 'dynamic_needles'
    setup_started = time.perf_counter()
    s.query(spec['watchlist']['ddl'])
    # Use generated validated inserts so metadata is exactly production-shaped.
    inserts = spec['watchlist']['inserts']
    prefix = inserts[0].split(' VALUES ', 1)[0] + ' VALUES '
    for start in range(0, len(inserts), 128):
        s.query(prefix + ', '.join(sql.split(' VALUES ', 1)[1] for sql in inserts[start:start+128]))
    s.query('CREATE TABLE ingest_src (id UInt64, v String) ENGINE=MergeTree ORDER BY id')
    s.query('CREATE TABLE ingest_hits (id UInt64, indicator_id Int64, view String) ENGINE=MergeTree ORDER BY id')
    s.query(spec['watchlist']['mvs'][strategy])
    print(json.dumps({'ingest_setup_seconds':time.perf_counter()-setup_started, 'strategy':strategy}), flush=True)
    for repeat in range(args.repeats):
        s.query('TRUNCATE TABLE ingest_src')
        s.query('TRUNCATE TABLE ingest_hits')
        print(json.dumps({'insert_started':True,'strategy':strategy,'repeat':repeat}), flush=True)
        started = time.perf_counter()
        s.query('INSERT INTO ingest_src SELECT id,v FROM bench')
        elapsed = time.perf_counter()-started
        hits = int(rows('SELECT count() FROM ingest_hits')[0][0])
        print(json.dumps({'strategy':strategy,'repeat':repeat,'hits':hits,'insert_wall_seconds':elapsed,'rows_per_second':spec['rows']/elapsed}), flush=True)
        if hits != spec['rows']//100:
            raise AssertionError((strategy,hits))
    sys.exit(0)
names = [args.strategy] if args.strategy else list(spec['queries'])
slow = set()
for repeat in range(args.repeats):
    for name in names[repeat % len(names):] + names[:repeat % len(names)]:
        if name in slow:
            continue
        started = time.perf_counter()
        hits = sum(int(rows('SELECT count() FROM (' + sql + ')')[0][0]) for sql in spec['queries'][name])
        elapsed = time.perf_counter() - started
        print(json.dumps({'strategy': name, 'repeat': repeat, 'queries':len(spec['queries'][name]), 'max_sql_bytes':max(len(q.encode()) for q in spec['queries'][name]), 'hits':hits, 'wall_seconds':elapsed}), flush=True)
        if hits != spec['rows']//100:
            raise AssertionError((name,hits))
        if elapsed >= 60:
            slow.add(name)
            print(json.dumps({'skip_further_repeats':name,'reason':'completed sample exceeded 60 seconds'}), flush=True)
